  "hechos": [
    {"id": "H1", "texto": "Puerto Celeste decretó toque de queda nocturno.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6", "P7"]},
    {"id": "H2", "texto": "El toque de queda regirá entre las 10:00 p. m. y las 5:00 a. m.", "tipo": "dato", "paginas": ["P1", "P3", "P4"]},
    {"id": "H3", "texto": "La medida estará vigente durante 15 días.", "tipo": "dato", "paginas": ["P2", "P3", "P7"]},
    {"id": "H4", "texto": "Incumplir la medida puede resultar en multas de hasta 800.000 pesos.", "tipo": "dato", "paginas": ["P1", "P5", "P6"]},
    {"id": "H5", "texto": "La restricción responde al incremento de robos a viviendas en las últimas semanas.", "tipo": "dato", "paginas": ["P2", "P3", "P4", "P7"]},
    {"id": "H6", "texto": "Se planea extender la medida a todo el departamento.", "tipo": "dato", "paginas": ["P1", "P3", "P4", "P5"]}
